use crate::{error,lock,runtime,safety,win,Result,Shared};
use serde::Serialize;
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{io::Read,os::windows::io::OwnedHandle,path::{Path,PathBuf},process::{Child,Command,Stdio},time::{Duration,Instant}};
use tauri::State;
use tokio::io::{AsyncReadExt,AsyncWriteExt,BufReader};
const VERSION:&str="2.0.2";
const HASH:&str="6e62da9f56a3bcf72e0c62c29e94609c847cc9b110c460f68b20035525985238";
const URL:&str="https://github.com/playit-cloud/playit-agent/releases/download/v2.0.2/playitd-windows-x86_64-signed.exe";
const CREDENTIAL:&str="MineHost/playit-agent/v1";
pub struct ManagedAgent{child:Child,job:Option<OwnedHandle>,pipe:String,session:PathBuf}
impl ManagedAgent{pub fn alive(&mut self)->bool{matches!(self.child.try_wait(),Ok(None))}fn endpoint(&self)->(String,u32){(self.pipe.clone(),self.child.id())}}
impl Drop for ManagedAgent{fn drop(&mut self){drop(self.job.take());let _=self.child.kill();let _=self.child.wait();let _=std::fs::remove_dir_all(&self.session);}}
pub struct Claim{code:String,created:Instant}
fn binary(root:&Path)->PathBuf{root.join(format!("network/tools/playitd-{VERSION}.exe"))}
fn verify(path:&Path)->Result<()>{safety::reject_links(path)?;let mut file=std::fs::File::open(path).map_err(error)?;if file.metadata().map_err(error)?.len()>32*1024*1024{return Err("Agent binary exceeds expected size".into());}let mut hash=Sha256::new();let mut buffer=[0;65536];loop{let n=file.read(&mut buffer).map_err(error)?;if n==0{break;}hash.update(&buffer[..n]);}if format!("{:x}",hash.finalize())!=HASH{return Err("Agent checksum differs from the pinned official release; install the verified copy".into());}Ok(())}
fn begin(shared:&Shared)->Result<crate::Operation>{let mut inner=lock(shared)?;if !inner.busy.insert("playit-operation".into()){return Err("Wait for the current agent operation".into());}Ok(crate::Operation{shared:shared.clone(),id:"playit-operation".into()})}
#[tauri::command]pub async fn playit_install(state:State<'_,Shared>,consent:bool,on_progress:tauri::ipc::Channel<runtime::DownloadProgress>)->Result<()> {
    if !consent{return Err("Confirm downloading the official standalone playit agent".into());}let _operation=begin(&state)?;let root={let mut inner=lock(&state)?;if inner.agent.as_mut().is_some_and(ManagedAgent::alive){return Err("Stop the managed agent before replacing its binary".into());}inner.root.clone()};let path=binary(&root);let folder=path.parent().ok_or("Missing agent directory")?;safety::reject_links(folder)?;std::fs::create_dir_all(folder).map_err(error)?;runtime::download(URL,HASH,&path,&|value|{let _=on_progress.send(value);}).await?;verify(&path)
}
#[tauri::command]pub async fn playit_import_agent(state:State<'_,Shared>,source:String,consent:bool)->Result<()> {
    if !consent{return Err("Confirm using this existing agent binary".into());}let shared=state.inner().clone();tauri::async_runtime::spawn_blocking(move||{let _operation=begin(&shared)?;let root={let mut inner=lock(&shared)?;if inner.agent.as_mut().is_some_and(ManagedAgent::alive){return Err("Stop the managed agent first".into());}inner.root.clone()};let source=PathBuf::from(source);verify(&source)?;let path=binary(&root);safety::reject_links(&path)?;std::fs::create_dir_all(path.parent().ok_or("Missing parent")?).map_err(error)?;if source!=path{let bytes=std::fs::read(source).map_err(error)?;safety::atomic_write(&path,&bytes)?;}verify(&path)}).await.map_err(error)?
}
async fn api(path:&str,input:&Value)->Result<Value>{let mut response=runtime::client()?.post(format!("https://api.playit.gg{path}")).timeout(Duration::from_secs(15)).json(input).send().await.map_err(error)?.error_for_status().map_err(error)?;let mut bytes=Vec::new();while let Some(chunk)=response.chunk().await.map_err(error)?{if bytes.len()+chunk.len()>65536{return Err("Playit response exceeds limit".into());}bytes.extend_from_slice(&chunk);}let value:Value=serde_json::from_slice(&bytes).map_err(error)?;if value["status"]!="success"{return Err("Playit declined the claim request; retry the browser flow. No credential was exposed.".into());}Ok(value["data"].clone())}
#[tauri::command]pub async fn playit_claim(state:State<'_,Shared>,consent:bool)->Result<String>{if !consent{return Err("Approve connecting MineHost to your playit account".into());}let _operation=begin(&state)?;if win::credential_read(CREDENTIAL)?.is_some(){return Err("An agent is already linked; forget it explicitly before claiming another".into());}let code=uuid::Uuid::new_v4().simple().to_string()[..10].to_string();api("/claim/setup",&json!({"code":code,"agent_type":"self-managed","version":"MineHost 0.5.0 (playit agent 2.0.2)"})).await?;lock(&state)?.claim=Some(Claim{code:code.clone(),created:Instant::now()});Ok(format!("https://playit.gg/claim/{code}"))}
#[tauri::command]pub async fn playit_finish_claim(state:State<'_,Shared>)->Result<String>{let _operation=begin(&state)?;let code={let inner=lock(&state)?;let claim=inner.claim.as_ref().ok_or("Start agent linking first")?;if claim.created.elapsed()>Duration::from_secs(3600){return Err("Claim expired; start again".into());}claim.code.clone()};let setup=api("/claim/setup",&json!({"code":code,"agent_type":"self-managed","version":"MineHost 0.5.0 (playit agent 2.0.2)"})).await?;let phase=setup.as_str().ok_or("Unknown claim response")?;match phase{"UserAccepted"=>{let value=api("/claim/exchange",&json!({"code":code})).await?;let secret=value["secret_key"].as_str().filter(|v|v.len()>=16&&v.len()<=256&&v.bytes().all(|b|b.is_ascii_hexdigit())).ok_or("Invalid agent credential")?;win::credential_write(CREDENTIAL,secret)?;lock(&state)?.claim=None;Ok("linked".into())},"UserRejected"=>{lock(&state)?.claim=None;Ok("rejected".into())},"WaitingForUserVisit"|"WaitingForUser"=>Ok("waiting".into()),_=>Err("Unsupported claim state".into())}}
fn spawn(root:&Path)->Result<ManagedAgent>{let path=binary(root);verify(&path)?;let session=root.join("network/private").join(uuid::Uuid::new_v4().to_string());win::protect_directory(&session)?;let pipe=format!(r"\\.\pipe\minehost-playit-{}",uuid::Uuid::new_v4());let mut command=Command::new(path);runtime::hide_window(&mut command);command.arg("--secret-path").arg(session.join("playit.toml")).arg("--socket-path").arg(&pipe).arg("--log-path").arg(session.join("agent.log")).arg("--cert-dir").arg(session.join("certs")).env_remove("SECRET_KEY").env_remove("SECRET_KEY_FILE").env_remove("API_BASE").stdin(Stdio::null()).stdout(Stdio::null()).stderr(Stdio::null());let mut child=command.spawn().map_err(error)?;let job=match win::kill_on_close_job(&child){Ok(job)=>job,Err(e)=>{let _=child.kill();let _=child.wait();return Err(e);}};Ok(ManagedAgent{child,job:Some(job),pipe,session})}
async fn frame(reader:&mut BufReader<tokio::net::windows::named_pipe::NamedPipeClient>)->Result<Value>{let mut bytes=Vec::new();loop{let byte=reader.read_u8().await.map_err(error)?;if byte==b'\n'{break;}bytes.push(byte);if bytes.len()>512*1024{return Err("Agent IPC frame exceeds limit".into());}}serde_json::from_slice(&bytes).map_err(error)}
async fn ipc(pipe:&str,pid:u32,request:Value)->Result<Value>{use std::os::windows::io::AsRawHandle;tokio::time::timeout(Duration::from_secs(5),async{let client=tokio::net::windows::named_pipe::ClientOptions::new().open(pipe).map_err(error)?;win::verify_pipe_owner(client.as_raw_handle(),pid)?;let mut reader=BufReader::new(client);let hello=frame(&mut reader).await?;if hello["message_kind"]!="hello"||hello.pointer("/data/protocol/ipc_version").and_then(Value::as_u64)!=Some(3){return Err("Unsupported playit IPC protocol".into());}let message=json!({"ipc_version":3,"request_id":1,"request":request}).to_string()+"\n";reader.get_mut().write_all(message.as_bytes()).await.map_err(error)?;reader.get_mut().flush().await.map_err(error)?;let response=frame(&mut reader).await?;if response["message_kind"]!="response"||response.pointer("/data/ipc_version").and_then(Value::as_u64)!=Some(3)||response.pointer("/data/request_id").and_then(Value::as_u64)!=Some(1){return Err("Invalid agent response".into());}let reply=response.pointer("/data/response").ok_or("Missing agent response")?;if reply["type"]=="error"{return Err("Agent rejected the local request; check its status or relink it".into());}Ok(reply.clone())}).await.map_err(|_|"Agent IPC request timed out".to_string())?}
#[tauri::command]pub async fn playit_start(state:State<'_,Shared>,consent:bool)->Result<()> {if !consent{return Err("Confirm starting playit and exposing configured tunnels to the Internet".into());}let _operation=begin(&state)?;let secret=win::credential_read(CREDENTIAL)?.ok_or("Link your playit account first")?;let root={let mut inner=lock(&state)?;if inner.agent.as_mut().is_some_and(ManagedAgent::alive){return Err("Managed agent is already running".into());}inner.agent=None;inner.root.clone()};let agent=tauri::async_runtime::spawn_blocking(move||spawn(&root)).await.map_err(error)??;let (pipe,pid)=agent.endpoint();lock(&state)?.agent=Some(agent);let deadline=Instant::now()+Duration::from_secs(8);let result=loop{match ipc(&pipe,pid,json!({"type":"set_secret","secret":secret})).await{Ok(response)=>{break if response["type"]=="set_secret"{Ok(())}else{Err("Agent did not accept credential provisioning".into())}},Err(e)=>{if Instant::now()>deadline{break Err(e);}tokio::time::sleep(Duration::from_millis(150)).await;}}};if result.is_err(){let agent=lock(&state)?.agent.take();drop(agent);}result}
#[tauri::command]pub async fn playit_stop(state:State<'_,Shared>,consent:bool)->Result<()> {if !consent{return Err("Confirm stopping the managed tunnels".into());}let _operation=begin(&state)?;let endpoint={lock(&state)?.agent.as_ref().map(ManagedAgent::endpoint)};if let Some((pipe,pid))=endpoint{let _=ipc(&pipe,pid,json!({"type":"stop"})).await;for _ in 0..15{let alive={lock(&state)?.agent.as_mut().is_some_and(ManagedAgent::alive)};if !alive{break;}tokio::time::sleep(Duration::from_millis(100)).await;}}let agent=lock(&state)?.agent.take();tauri::async_runtime::spawn_blocking(move||drop(agent)).await.map_err(error)?;Ok(())}
#[tauri::command]pub async fn playit_forget(state:State<'_,Shared>,consent:bool)->Result<()>{if !consent{return Err("Confirm forgetting the local playit credential".into());}let _operation=begin(&state)?;if lock(&state)?.agent.as_mut().is_some_and(ManagedAgent::alive){return Err("Stop the managed agent before forgetting its credential".into());}win::credential_delete(CREDENTIAL)?;lock(&state)?.claim=None;Ok(())}
#[derive(Serialize)]#[serde(rename_all="camelCase")]pub struct Tunnel{pub(crate) id:String,pub(crate) address:String,destination:String,pub(crate) disabled:bool,pub(crate) matches_profile:bool}
#[derive(Serialize)]#[serde(rename_all="camelCase")]pub struct Status{installed:bool,version:&'static str,linked:bool,running:bool,phase:String,pub(crate) tunnels:Vec<Tunnel>}
fn tunnels(value:&Value,port:Option<u16>)->Vec<Tunnel>{value.pointer("/data/tunnels").and_then(Value::as_array).into_iter().flatten().take(256).filter_map(|t|{let id=t["id"].as_str()?;uuid::Uuid::parse_str(id).ok()?;let address=t["display_address"].as_str()?.chars().take(512).collect();let destination=t["destination"].as_str()?.chars().take(512).collect::<String>();let matches_profile=port.is_some_and(|p|[format!("127.0.0.1:{p}"),format!("localhost:{p}"),format!("[::1]:{p}")].contains(&destination));Some(Tunnel{id:id.into(),address,destination,disabled:t["is_disabled"].as_bool().unwrap_or(true),matches_profile})}).collect()}
#[tauri::command]pub async fn playit_status(state:State<'_,Shared>,id:Option<String>)->Result<Status>{let(root,endpoint,port)={let mut inner=lock(&state)?;let port=if let Some(id)=&id{Some(crate::load(&inner,id)?.port)}else{None};if inner.agent.as_mut().is_some_and(|v|!v.alive()){inner.agent=None;}(inner.root.clone(),inner.agent.as_ref().map(ManagedAgent::endpoint),port)};let installed=binary(&root).is_file();let mut status=Status{installed,version:VERSION,linked:win::credential_read(CREDENTIAL)?.is_some(),running:endpoint.is_some(),phase:"stopped".into(),tunnels:vec![]};if let Some((pipe,pid))=endpoint{match ipc(&pipe,pid,json!({"type":"get_state"})).await{Ok(reply)if reply["type"]=="state"=>{let lifecycle=&reply["data"];status.phase=lifecycle["state"].as_str().unwrap_or("unknown").to_string();if status.phase=="running"{status.tunnels=tunnels(lifecycle,port);}},_=>status.phase="unavailable".into()}}Ok(status)}
#[tauri::command]pub fn network_open_link(kind:String,claim_url:Option<String>)->Result<()>{let url=match kind.as_str(){"playit-dashboard"=>"https://playit.gg/account/tunnels".into(),"playit-domains"=>"https://playit.gg/support/add-an-external-domain-to-playit-gg/".into(),"playit-claim"=>{let value=claim_url.ok_or("Missing claim URL")?;let parsed=reqwest::Url::parse(&value).map_err(error)?;if parsed.scheme()!="https"||parsed.host_str()!=Some("playit.gg")||!parsed.path().starts_with("/claim/")||parsed.query().is_some()||parsed.fragment().is_some(){return Err("Invalid playit claim URL".into());}value},_=>return Err("Unknown network help page".into())};Command::new("explorer.exe").arg(url).spawn().map_err(error)?;Ok(())}
#[cfg(test)]mod tests{use super::*;#[test]fn tunnel_snapshot_excludes_agent_secrets_and_checks_destination(){let value=json!({"state":"running","data":{"login_link":"sensitive","tunnels":[{"id":uuid::Uuid::new_v4().to_string(),"display_address":"test.ply.gg:1234","destination":"127.0.0.1:25565","is_disabled":false}]}});let result=tunnels(&value,Some(25565));assert!(result[0].matches_profile);assert!(!serde_json::to_string(&result).unwrap().contains("sensitive"));}#[tokio::test]#[ignore="Pinned signed agent, GitHub Windows runner only; no account or tunnel created"]async fn agent_binary_and_ipc_contract(){let stage=crate::archive::Stage::new(&std::env::temp_dir()).unwrap();let path=binary(&stage.0);std::fs::create_dir_all(path.parent().unwrap()).unwrap();runtime::download(URL,HASH,&path,&|_|{}).await.unwrap();verify(&path).unwrap();let output=Command::new(&path).arg("--help").output().unwrap();assert!(output.status.success());assert!(String::from_utf8_lossy(&output.stdout).contains("--socket-path"));let mut agent=spawn(&stage.0).unwrap();let(pipe,pid)=agent.endpoint();let deadline=Instant::now()+Duration::from_secs(8);loop{match ipc(&pipe,pid,json!({"type":"get_state"})).await{Ok(reply)=>{assert_eq!(reply["type"],"state");assert_eq!(reply["data"]["state"],"waiting_for_secret");break;},Err(e)=>{assert!(Instant::now()<deadline,"{e}");tokio::time::sleep(Duration::from_millis(100)).await;}}}let _=ipc(&pipe,pid,json!({"type":"stop"})).await;let _=agent.alive();drop(agent);}}
